#stage .p-scene{ position:relative; width:100%; height:100%; }#stage .p-hook{
  position:absolute; inset:0; z-index:8; display:flex; flex-direction:column;
  align-items:center; justify-content:center; gap:14px; text-align:center;
  background:rgba(14,20,32,.96);
  opacity:0; transform:scale(.98); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}#stage .p-hook.on{ opacity:1; transform:none; }#stage .p-hook-l1{ color:var(--text-dim); font-size:40px; font-weight:600; }#stage .p-hook-l1 b{ color:var(--text-primary); font-family:var(--font-mono); }#stage .p-hook-code{
  font-family:var(--font-mono); font-size:46px; font-weight:700; color:var(--accent-cyan);
