  text-shadow:0 0 80px rgba(58,160,255,.45);
}#stage .p-hook-l2{
  color:var(--accent-1); font-size:30px; font-weight:700; margin-top:16px;
  opacity:0; transition:opacity .3s ease;
}#stage .p-hook-l2.on{ opacity:1; }#stage .p-topbar{ position:absolute; top:0; left:0; width:992px; height:50px; display:flex; align-items:center; gap:16px; }#stage .p-badge{
  padding:9px 22px; border-radius:100px; background:rgba(58,160,255,.16);
