}#stage .p-state{ color:var(--text-dim); font-family:var(--font-mono); font-size:22px; }#stage .p-editor{ position:absolute; top:60px; left:0; width:992px; height:286px; }#stage .p-file{ color:var(--text-dim); font-family:var(--font-mono); font-size:20px; margin-left:14px; }#stage .p-editor .body{ position:relative; font-size:27px; line-height:1.7; }#stage .p-code{ display:none; }#stage .p-code.on{ display:block; }#stage .p-editor .nu{ color:#b5cea8; }#stage .p-line{
  opacity:0; transform:translateX(-10px); border-radius:8px;
  transition:opacity .24s ease, transform .24s ease, background .24s ease;
}#stage .p-line.show{ opacity:1; transform:none; }#stage .p-line.run{ background:rgba(58,160,255,.16); box-shadow:inset 3px 0 0 var(--accent-1); }#stage .p-line.bad{ background:rgba(244,74,106,.14); box-shadow:inset 3px 0 0 var(--danger); }#stage .p-mem{ position:absolute; top:368px; left:0; width:992px; height:400px; padding:24px 24px 0; }#stage .p-grid{ position:relative; width:944px; height:318px; margin-top:14px; }#stage .p-name{
  position:absolute; left:0; width:120px; height:76px; border-radius:20px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(20,27,43,.9); border:1.5px solid var(--border);
  color:#fff; font-family:var(--font-mono); font-size:38px; font-weight:700;
  opacity:0; transform:translateX(-14px);
  transition:opacity .26s ease, transform .26s cubic-bezier(.22,1,.36,1);
}#stage .p-name.on{ opacity:1; transform:none; border-color:rgba(58,160,255,.5); }#stage .p-name.sm{ font-size:24px; letter-spacing:0; }#stage #p-n-a{ top:46px; }#stage #p-n-b{ top:176px; }#stage .p-conn{
  position:absolute; height:4px; border-radius:2px; transform-origin:0 50%;
  background:linear-gradient(90deg, rgba(58,160,255,.25), var(--accent-1));
  opacity:0; transition:opacity .26s ease;
}#stage .p-conn.on{ opacity:1; }#stage .p-conn::after{
  content:""; position:absolute; right:-2px; top:-8px;
  border-left:18px solid var(--accent-1);
  border-top:10px solid transparent; border-bottom:10px solid transparent;
}#stage #p-c-a{ left:120px; top:82px; width:280px; }#stage #p-c-b1{ left:120px; top:212px; width:310px; transform:rotate(-25.6deg); }#stage #p-c-b2{ left:120px; top:212px; width:281px; transform:rotate(3.3deg); }#stage .p-obj{
  position:absolute; left:400px; width:504px; padding:20px 26px; border-radius:22px;
  background:linear-gradient(180deg, var(--bg-panel-2), var(--bg-panel));
  border:1.5px solid rgba(58,160,255,.4); box-shadow:0 0 34px rgba(58,160,255,.14);
  opacity:0; transform:scale(.96);
  transition:opacity .28s ease, transform .28s cubic-bezier(.22,1,.36,1);
}#stage .p-obj.on{ opacity:1; transform:none; }#stage #p-o-1{ top:20px; }#stage #p-o-2{ top:170px; }#stage .p-otype{
  display:inline-block; padding:4px 14px; border-radius:8px; margin-bottom:10px;
  background:rgba(34,211,238,.14); border:1px solid rgba(34,211,238,.34);
  color:var(--accent-cyan); font-family:var(--font-mono); font-size:19px; font-weight:700;
}#stage .p-oval{ color:#fff; font-family:var(--font-mono); font-size:38px; font-weight:700; }#stage .p-oid{ color:var(--text-dim); font-family:var(--font-mono); font-size:20px; margin-top:8px; }#stage .p-tag{
  position:absolute; top:18px; right:22px; padding:6px 16px; border-radius:100px;
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:.5px;
  opacity:0; transition:opacity .24s ease;
}#stage .p-tag.on{ opacity:1; }#stage .p-tag-ok{ background:rgba(63,185,80,.16); border:1px solid rgba(63,185,80,.5); color:var(--success); }#stage .p-tag-new{ background:rgba(240,166,74,.16); border:1px solid rgba(240,166,74,.5); color:var(--warn); }#stage .p-tag-bad{ background:rgba(244,74,106,.16); border:1px solid rgba(244,74,106,.5); color:var(--danger); }#stage .p-panels{ position:absolute; top:790px; left:0; width:992px; height:234px; }#stage .p-panel{
  position:absolute; inset:0; padding:22px 28px; opacity:0; transform:scale(.98);
  pointer-events:none; transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
  display:flex; flex-direction:column; justify-content:center;
}#stage .p-panel.on{ opacity:1; transform:none; }#stage .p-cols{ display:flex; gap:26px; height:100%; }#stage .p-col{ flex:1; display:flex; flex-direction:column; gap:11px; }#stage .p-colh{ font-size:20px; font-weight:800; letter-spacing:1.4px; }#stage .p-ok{ color:var(--success); }#stage .p-hot{ color:var(--warn); }#stage .p-trow{ display:flex; gap:10px; }#stage .p-trow code{
  padding:7px 14px; border-radius:9px; background:rgba(20,27,43,.75);
  border:1px solid var(--border); color:var(--text-primary);
  font-family:var(--font-mono); font-size:21px; font-weight:600;
}#stage .p-note{ color:var(--text-dim); font-size:21px; font-weight:600; margin-top:14px; }#stage .p-col .p-note{ margin-top:auto; }#stage .p-note.p-bad{ color:var(--danger); margin-top:16px; }#stage .p-calls{ margin-top:16px; display:flex; flex-direction:column; gap:10px; }#stage .p-crow{ display:flex; align-items:center; gap:20px; font-family:var(--font-mono); font-size:26px; }#stage .p-call{ color:var(--text-primary); min-width:190px; }#stage .p-arrow{ color:var(--text-dim); }#stage .p-res{ color:var(--success); font-weight:700; }#stage .p-res.p-bad{ color:var(--danger); }#stage .p-fix{ margin-top:16px; display:flex; flex-direction:column; gap:12px; }#stage .p-frow{ display:flex; align-items:center; gap:16px; font-family:var(--font-mono); font-size:24px; }#stage .p-frow code{ color:var(--success); }#stage .p-c{ color:var(--success); font-size:26px; font-weight:800; width:24px; }#stage .p-fnote{ color:var(--text-dim); font-size:20px; margin-left:auto; }#stage .p-rule{ display:flex; flex-direction:column; gap:14px; }#stage .p-rrow{ display:flex; align-items:center; gap:20px; }#stage .p-rk{
  min-width:150px; padding:8px 18px; border-radius:10px; text-align:center;
  background:rgba(20,27,43,.8); border:1.5px solid var(--border);
  font-family:var(--font-mono); font-size:24px; font-weight:700;
}#stage .p-rv{ color:var(--text-primary); font-size:23px; font-weight:600; }

stages.js:
MSD.cls('#p-hook', 'on', true);
MSD.cls('#p-hook-l2', 'on', false);
MSD.after(120, function(){ MSD.punch('#p-hook-big', 2); });
MSD.after(1250, function(){ MSD.cls('#p-hook-l2', 'on', true); MSD.sfx.pop(); });

MSD.cls('#p-hook', 'on', false);
MSD.unfocus();
MSD.cls('.p-line', 'show', false);
MSD.cls('.p-line', 'run', false);
MSD.cls('.p-code', 'on', false);
MSD.cls('#p-code-1', 'on', true);
MSD.cls('.p-panel', 'on', false);
MSD.cls('#p-o-2, #p-c-b2, #p-g1, #p-g2', 'on', false);
MSD.cls('#p-n-a, #p-n-b', 'sm', false);
MSD.cls('#p-g1', 'p-tag-bad', false);
MSD.cls('#p-g1', 'p-tag-ok', true);
MSD.q('#p-n-a-t').textContent = 'a';
MSD.q('#p-n-b-t').textContent = 'b';
MSD.q('#p-t1').textContent = 'list';
MSD.q('#p-v1').textContent = '[1, 2, 3]';
MSD.q('#p-i1').textContent = 'id 0x1f04';
MSD.q('#p-g1').textContent = 'same id';
MSD.q('#p-pt-k').textContent = 'id(a) == id(b)';
MSD.q('#p-pt-v').textContent = 'True';
MSD.q('#p-pt-n').textContent = 'One object in memory. Two names on it.';
MSD.cls('#p-pt-v', 'p-bad', false);
MSD.q('#p-state').textContent = 'two names, one object';
MSD.after(80, function(){ MSD.cls('#p-l1-1', 'show', true); MSD.sfx.tick(); });
MSD.after(400, function(){ MSD.cls('#p-o-1', 'on', true); MSD.cls('#p-n-a', 'on', true); MSD.sfx.blip(0); });
MSD.after(760, function(){ MSD.cls('#p-c-a', 'on', true); MSD.sfx.data(0); });
MSD.after(1200, function(){ MSD.cls('#p-l1-2', 'show', true); MSD.cls('#p-n-b', 'on', true); MSD.sfx.blip(2); });
MSD.after(1560, function(){ MSD.cls('#p-c-b1', 'on', true); MSD.flash('#p-o-1'); MSD.sfx.lock(); });
MSD.after(2000, function(){ MSD.cls('#p-p-point', 'on', true); MSD.punch('#p-pt-row', 4); });

MSD.cls('#p-code-1', 'on', true);
MSD.cls('#p-l1-1, #p-l1-2', 'show', true);
MSD.cls('#p-n-a, #p-n-b, #p-o-1, #p-c-a, #p-c-b1, #p-p-point', 'on', true);
MSD.q('#p-pt-k').textContent = 'print(a)';
MSD.q('#p-pt-v').textContent = '?';
MSD.q('#p-pt-n').textContent = 'You never touched a. The object under it changed.';
MSD.focus('#p-o-1', '#p-editor');
MSD.after(120, function(){ MSD.cls('#p-l1-3', 'show', true); MSD.cls('#p-l1-3', 'run', true); MSD.sfx.blip(3); });
MSD.after(820, function(){
  MSD.q('#p-v1').textContent = '[1, 2, 3, 4]';
  MSD.punch('#p-o-1', 4);
});
MSD.after(1250, function(){ MSD.cls('#p-g1', 'on', true); MSD.flash('#p-i1'); MSD.sfx.lock(); });
MSD.after(1750, function(){
  MSD.cls('#p-l1-4', 'show', true);
  MSD.q('#p-pt-v').textContent = '[1, 2, 3, 4]';
  MSD.punch('#p-pt-row', 1);
  MSD.sfx.ding();
});

MSD.unfocus();
MSD.cls('.p-line', 'show', false);
MSD.cls('.p-line', 'run', false);
MSD.cls('.p-code', 'on', false);
MSD.cls('#p-code-2', 'on', true);
MSD.cls('#p-g1, #p-g2, #p-o-2, #p-c-b2', 'on', false);
MSD.q('#p-n-a-t').textContent = 't';
MSD.q('#p-n-b-t').textContent = 's';
MSD.q('#p-t1').textContent = 'str';
MSD.q('#p-v1').textContent = '"hi"';
MSD.q('#p-i1').textContent = 'id 0x9c11';
MSD.q('#p-t2').textContent = 'str';
MSD.q('#p-v2').textContent = '"hi!"';
MSD.q('#p-i2').textContent = 'id 0x9c88';
MSD.q('#p-g2').textContent = 'new object';
MSD.q('#p-pt-k').textContent = 'print(t)';
MSD.q('#p-pt-v').textContent = '"hi"';
MSD.q('#p-pt-n').textContent = 'Only s moved. t is still on the old string.';
MSD.q('#p-state').textContent = 'strings cannot be edited';
MSD.cls('#p-n-a, #p-n-b, #p-o-1, #p-c-a, #p-c-b1, #p-p-point', 'on', true);
MSD.cls('#p-l2-1, #p-l2-2', 'show', true);
MSD.after(220, function(){ MSD.cls('#p-l2-3', 'show', true); MSD.cls('#p-l2-3', 'run', true); MSD.sfx.blip(3); });
MSD.after(900, function(){ MSD.cls('#p-o-2, #p-g2', 'on', true); MSD.sfx.pop(); });
MSD.after(1350, function(){
  MSD.cls('#p-c-b1', 'on', false);
  MSD.cls('#p-c-b2', 'on', true);
  MSD.punch('#p-n-b', 3);
  MSD.sfx.swipe();
});
MSD.after(1900, function(){
  MSD.cls('#p-l2-4', 'show', true);
  MSD.flash('#p-o-1');
  MSD.punch('#p-pt-row', 2);
  MSD.sfx.lock();
});

MSD.cls('.p-panel', 'on', false);
MSD.hide('#p-p-types .msd-reveal');
MSD.cls('#p-p-types', 'on', true);
MSD.focus('.p-panels', '.p-mem, #p-editor');
MSD.q('#p-state').textContent = 'two families of types';
MSD.after(180, function(){ MSD.show('#p-p-types .msd-reveal', 190); });
MSD.after(1500, function(){ MSD.flash('#p-p-types'); MSD.sfx.sparkle(); });

MSD.cls('.p-line', 'show', false);
MSD.cls('.p-line', 'run', false);
MSD.cls('.p-code', 'on', false);
MSD.cls('#p-code-3', 'on', true);
MSD.cls('.p-panel', 'on', false);
MSD.hide('#p-p-trap .msd-reveal');
MSD.cls('#p-p-trap', 'on', true);
MSD.unfocus();
// The diagram now tracks the default list itself: one object, reused.
MSD.cls('#p-n-b, #p-c-b1, #p-c-b2, #p-o-2, #p-g2, #p-g1', 'on', false);
MSD.cls('#p-n-a', 'sm', true);
MSD.cls('#p-g1', 'p-tag-ok', false);
MSD.cls('#p-g1', 'p-tag-bad', true);
MSD.q('#p-n-a-t').textContent = 'cart';
MSD.q('#p-t1').textContent = 'list';
MSD.q('#p-v1').textContent = "['a']";
MSD.q('#p-i1').textContent = 'id 0x3a10';
MSD.q('#p-g1').textContent = 'same list';
MSD.cls('#p-n-a, #p-o-1, #p-c-a', 'on', true);
MSD.q('#p-file').textContent = 'cart.py';
MSD.q('#p-state').textContent = 'calling add() twice';
MSD.qa('#p-code-3 .p-line').forEach(function(el, i){
  MSD.after(80 + i * 130, function(){ el.classList.add('show'); MSD.sfx.tick(); });
});
MSD.after(820, function(){ MSD.cls('#p-cr-1', 'show', true); MSD.sfx.blip(1); });
MSD.after(1400, function(){
  MSD.q('#p-v1').textContent = "['a', 'b']";
  MSD.cls('#p-g1', 'on', true);
  MSD.punch('#p-o-1', 3);
});
MSD.after(1700, function(){ MSD.cls('#p-cr-2', 'show', true); MSD.sfx.blip(4); });
MSD.after(2150, function(){ MSD.cls('#p-l3-1', 'bad', true); MSD.shake('#p-p-trap'); });

MSD.cls('.p-line', 'show', false);
MSD.cls('.p-line', 'run', false);
MSD.cls('.p-line', 'bad', false);
MSD.cls('.p-code', 'on', false);
MSD.cls('#p-code-4', 'on', true);
MSD.cls('.p-panel', 'on', false);
MSD.hide('#p-p-fix .msd-reveal');
MSD.cls('#p-p-fix', 'on', true);
MSD.unfocus();
// Each call now builds its own list, so the diagram shows two objects.
MSD.cls('#p-n-a, #p-n-b', 'sm', true);
MSD.q('#p-n-a-t').textContent = 'call 1';
MSD.q('#p-n-b-t').textContent = 'call 2';
MSD.q('#p-v1').textContent = "['a']";
MSD.q('#p-i1').textContent = 'id 0x3a10';
MSD.q('#p-t2').textContent = 'list';
MSD.q('#p-v2').textContent = "['b']";
MSD.q('#p-i2').textContent = 'id 0x71c4';
MSD.q('#p-g2').textContent = 'own list';
MSD.cls('#p-g1, #p-c-b1', 'on', false);
MSD.cls('#p-n-a, #p-n-b, #p-o-1, #p-c-a', 'on', true);
MSD.q('#p-state').textContent = 'new list per call';
MSD.after(1150, function(){ MSD.cls('#p-o-2, #p-c-b2, #p-g2', 'on', true); MSD.sfx.pop(); });
MSD.qa('#p-code-4 .p-line').forEach(function(el, i){
  MSD.after(80 + i * 120, function(){ el.classList.add('show'); MSD.sfx.tick(); });
});
MSD.after(900, function(){ MSD.show('#p-p-fix .msd-reveal', 260); });
MSD.after(1800, function(){ MSD.flash('#p-p-fix'); MSD.sfx.chime(); });

MSD.unfocus();
MSD.cls('.p-panel', 'on', false);
MSD.hide('#p-p-rule .msd-reveal');
MSD.cls('#p-p-rule', 'on', true);
MSD.cls('.p-line', 'run', false);
MSD.cls('.p-line', 'bad', false);
MSD.cls('.p-code', 'on', false);
MSD.cls('#p-code-1', 'on', true);
MSD.cls('#p-l1-1, #p-l1-2, #p-l1-3, #p-l1-4', 'show', true);
// Back to the canonical picture: one mutated object, one replaced object.
MSD.cls('#p-n-a, #p-n-b', 'sm', false);
MSD.cls('#p-g1', 'p-tag-bad', false);
MSD.cls('#p-g1', 'p-tag-ok', true);
MSD.q('#p-n-a-t').textContent = 'a';
MSD.q('#p-n-b-t').textContent = 's';
MSD.q('#p-t1').textContent = 'list';
MSD.q('#p-v1').textContent = '[1, 2, 3, 4]';
MSD.q('#p-i1').textContent = 'id 0x1f04';
MSD.q('#p-g1').textContent = 'same id';
MSD.q('#p-t2').textContent = 'str';
MSD.q('#p-v2').textContent = '"hi!"';
MSD.q('#p-i2').textContent = 'id 0x9c88';
MSD.q('#p-g2').textContent = 'new object';
MSD.cls('#p-n-a, #p-n-b, #p-o-1, #p-o-2, #p-c-a, #p-c-b2, #p-g1, #p-g2', 'on', true);
MSD.cls('#p-c-b1', 'on', false);
MSD.q('#p-file').textContent = 'memory.py';
MSD.q('#p-state').textContent = 'one rule, both cases';
MSD.after(200, function(){ MSD.show('#p-p-rule .msd-reveal', 420); });
MSD.after(1200, function(){ MSD.punch('#p-o-1', 2); });
MSD.after(1500, function(){ MSD.punch('#p-o-2', 4); MSD.sfx.sparkle(); });
